insert into public.theological_sources (id, title, author, kind, year, context, themes, url, verified) values
  ('catecismo-igreja-catolica', 'Catecismo da Igreja Católica', 'Igreja Católica (promulgado por São João Paulo II)', 'catecismo', 1992, 'Exposição orgânica da fé católica em quatro partes: a profissão da fé, a celebração do mistério cristão, a vida em Cristo e a oração cristã (§§ 1-2865).', array['fe-e-esperanca','oracao','eucaristia','santidade','fé','sacramentos','moral','oração','doutrina']::text[], 'https://www.vatican.va/archive/cathechism_po/index_new/prima-pagina-cic_po.html', true),
  ('compendio-catecismo', 'Compêndio do Catecismo da Igreja Católica', 'Papa Bento XVI (aprovação por Motu Proprio)', 'catecismo', 2005, 'Síntese fiel do Catecismo da Igreja Católica em forma de perguntas e respostas, aprovada por Bento XVI em 28 de junho de 2005.', array['fe-e-esperanca','fé','catequese','doutrina','sacramentos','oração']::text[], 'https://www.vatican.va/archive/compendium_ccc/documents/archive_2005_compendium-ccc_po.html', true),
  ('codigo-direito-canonico', 'Código de Direito Canónico', 'São João Paulo II (promulgação)', 'direito', 1983, 'Código que rege a disciplina da Igreja latina, promulgado em 1983; versão portuguesa em PDF no arquivo do Vaticano.', array['direito canônico','sacramentos','disciplina','igreja']::text[], 'https://www.vatican.va/archive/cod-iuris-canonici/portuguese/codex-iuris-canonici_po.pdf', true),
  ('dei-verbum', 'Constituição Dogmática Dei Verbum sobre a Revelação Divina', 'Concílio Vaticano II', 'concilio', 1965, 'Trata da Revelação divina, da relação entre Sagrada Escritura e Tradição e da inspiração e interpretação da Escritura na vida da Igreja.', array['palavra-de-deus','palavra de deus','revelação','escritura','tradição','magistério']::text[], 'https://www.vatican.va/archive/hist_councils/ii_vatican_council/documents/vat-ii_const_19651118_dei-verbum_po.html', true),
  ('lumen-gentium', 'Constituição Dogmática Lumen Gentium sobre a Igreja', 'Concílio Vaticano II', 'concilio', 1964, 'Apresenta o mistério da Igreja como sacramento de salvação, Povo de Deus, sua constituição hierárquica, o laicato e a vocação universal à santidade.', array['santidade','maria','missao','igreja','povo de deus','santidade','leigos','maria']::text[], 'https://www.vatican.va/archive/hist_councils/ii_vatican_council/documents/vat-ii_const_19641121_lumen-gentium_po.html', true),
  ('sacrosanctum-concilium', 'Constituição Sacrosanctum Concilium sobre a Sagrada Liturgia', 'Concílio Vaticano II', 'concilio', 1963, 'Estabelece princípios para a reforma e o incremento da liturgia, com destaque para a participação ativa dos fiéis.', array['eucaristia','adoracao','liturgia','eucaristia','participação','sacramentos','reforma litúrgica']::text[], 'https://www.vatican.va/archive/hist_councils/ii_vatican_council/documents/vat-ii_const_19631204_sacrosanctum-concilium_po.html', true),
  ('gaudium-et-spes', 'Constituição Pastoral Gaudium et Spes sobre a Igreja no mundo actual', 'Concílio Vaticano II', 'concilio', 1965, 'Aborda a relação da Igreja com o mundo contemporâneo: dignidade humana, consciência, liberdade, família, cultura, vida econômica e paz.', array['familia','missao','dignidade humana','mundo atual','família','paz','sociedade']::text[], 'https://www.vatican.va/archive/hist_councils/ii_vatican_council/documents/vat-ii_const_19651207_gaudium-et-spes_po.html', true),
  ('apostolicam-actuositatem', 'Decreto Apostolicam Actuositatem sobre o apostolado dos leigos', 'Concílio Vaticano II', 'concilio', 1965, 'Explica a natureza e a variedade do apostolado dos leigos e oferece orientações pastorais para seu exercício.', array['missao','leigos','apostolado','missão','evangelização']::text[], 'https://www.vatican.va/archive/hist_councils/ii_vatican_council/documents/vat-ii_decree_19651118_apostolicam-actuositatem_po.html', true),
  ('ad-gentes', 'Decreto Ad Gentes sobre a atividade missionária da Igreja', 'Concílio Vaticano II', 'concilio', 1965, 'Apresenta a atividade missionária como decorrente da própria natureza da Igreja, voltada à evangelização e à implantação da Igreja entre os povos.', array['missao','missão','evangelização','igreja missionária','povos']::text[], 'https://www.vatican.va/archive/hist_councils/ii_vatican_council/documents/vat-ii_decree_19651207_ad-gentes_po.html', true),
  ('unitatis-redintegratio', 'Decreto Unitatis Redintegratio sobre o ecumenismo', 'Concílio Vaticano II', 'concilio', 1964, 'Expõe os princípios católicos do ecumenismo e orientações para a busca da unidade entre os cristãos.', array['ecumenismo','unidade','diálogo','cristãos']::text[], 'https://www.vatican.va/archive/hist_councils/ii_vatican_council/documents/vat-ii_decree_19641121_unitatis-redintegratio_po.html', true),
  ('nostra-aetate', 'Declaração Nostra Aetate sobre a Igreja e as religiões não-cristãs', 'Concílio Vaticano II', 'concilio', 1965, 'Trata da relação da Igreja com as religiões não-cristãs, incluindo o judaísmo, e rejeita toda discriminação racial ou religiosa.', array['diálogo inter-religioso','judaísmo','fraternidade','religiões']::text[], 'https://www.vatican.va/archive/hist_councils/ii_vatican_council/documents/vat-ii_decl_19651028_nostra-aetate_po.html', true),
  ('dignitatis-humanae', 'Declaração Dignitatis Humanae sobre a liberdade religiosa', 'Concílio Vaticano II', 'concilio', 1965, 'Afirma o direito à liberdade religiosa como direito civil fundado na dignidade da pessoa humana.', array['liberdade religiosa','dignidade humana','consciência','sociedade']::text[], 'https://www.vatican.va/archive/hist_councils/ii_vatican_council/documents/vat-ii_decl_19651207_dignitatis-humanae_po.html', true),
  ('evangelii-nuntiandi', 'Exortação Apostólica Evangelii Nuntiandi sobre a evangelização no mundo contemporâneo', 'São Paulo VI', 'exortacao', 1975, 'Fruto do Sínodo de 1974, ensina que o testemunho de vida é o primeiro meio de evangelização, a ser completado pelo anúncio explícito, e trata da evangelização das culturas.', array['missao','palavra-de-deus','evangelização','testemunho','anúncio','cultura','missão']::text[], 'https://www.vatican.va/content/paul-vi/pt/apost_exhortations/documents/hf_p-vi_exh_19751208_evangelii-nuntiandi.html', true),
  ('redemptor-hominis', 'Carta Encíclica Redemptor Hominis', 'São João Paulo II', 'enciclica', 1979, 'Primeira encíclica de João Paulo II, dedicada a Cristo Redentor do homem e à verdade sobre o ser humano revelada em Cristo.', array['amor-de-deus','cristo','redenção','dignidade humana','antropologia']::text[], 'https://www.vatican.va/content/john-paul-ii/pt/encyclicals/documents/hf_jp-ii_enc_04031979_redemptor-hominis.html', true),
  ('dives-in-misericordia', 'Carta Encíclica Dives in Misericordia', 'São João Paulo II', 'enciclica', 1980, 'Encíclica sobre a misericórdia divina revelada em Deus Pai por meio de Cristo.', array['misericordia','perdao','conversao','misericórdia','deus pai','perdão','amor']::text[], 'https://www.vatican.va/content/john-paul-ii/pt/encyclicals/documents/hf_jp-ii_enc_30111980_dives-in-misericordia.html', true),
  ('redemptoris-missio', 'Carta Encíclica Redemptoris Missio', 'São João Paulo II', 'enciclica', 1990, 'Encíclica sobre a validade permanente do mandato missionário, apresentando a missão ad gentes como atividade primária e nunca concluída da Igreja.', array['missao','missão','evangelização','ad gentes','igreja missionária']::text[], 'https://www.vatican.va/content/john-paul-ii/pt/encyclicals/documents/hf_jp-ii_enc_07121990_redemptoris-missio.html', true),
