  ('novo-millennio-ineunte', 'Carta Apostólica Novo Millennio Ineunte', 'São João Paulo II', 'carta-apostolica', 2001, 'Escrita ao fim do Grande Jubileu de 2000, convida a Igreja a ''fazer-se ao largo'' (Lc 5,4) partindo da contemplação do rosto de Cristo.', array['santidade','oracao','missao','santidade','oração','contemplação','missão','jubileu']::text[], 'https://www.vatican.va/content/john-paul-ii/pt/apost_letters/2001/documents/hf_jp-ii_apl_20010106_novo-millennio-ineunte.html', true),
