  ('ninguem-te-ama-como-eu', 'Ninguém Te Ama Como Eu', 'Thiago Brado, Katholika', array['louvor']::text[], array['grupo de oração','encontro de jovens','retiro']::text[], 'https://open.spotify.com/track/2lPrtOzx9bI4kCMpt1msbZ', 'Clássico católico sobre o amor de Deus, bom para louvor e retiros.', true, 'spotify'),
  ('eis-o-tempo-da-conversao', 'Eis o tempo da conversão', 'Cantos do Hinário Litúrgico da CNBB', array['quaresma','conversao']::text[], array['retiro','pregação']::text[], 'https://open.spotify.com/track/49r5b7YsFKhRBMFzFc76wG', 'O título anuncia o tempo de conversão, marca própria da Quaresma.', true, 'spotify'),
  ('pecador-agora-e-tempo', 'Pecador, Agora É Tempo', 'Cantos do Hinário Litúrgico da CNBB', array['quaresma','conversao','perdao']::text[], array['retiro','pregação']::text[], 'https://open.spotify.com/track/7MaO7GgDnjcSEubuFkvuuI', 'Convida o pecador a voltar a Deus, tema penitencial da Quaresma.', true, 'spotify'),
  ('senhor-eis-aqui-o-teu-povo', 'Senhor, Eis Aqui o Teu Povo', 'Cantos do Hinário Litúrgico da CNBB', array['quaresma']::text[], array['retiro','pregação']::text[], 'https://open.spotify.com/track/0htyMfO1JVqQmWl5kXnJBi', 'Canto do repertório quaresmal da CNBB em que o povo se apresenta a Deus.', true, 'spotify'),
  ('se-conhecesses-o-dom-de-deus', 'Se conhecesses o dom de Deus', 'Cantos do Hinário Litúrgico da CNBB', array['quaresma']::text[], array['retiro','pregação']::text[], 'https://open.spotify.com/track/1Q5xPMsC58azuZ8zdW0Ej7', 'Remete ao encontro de Jesus com a samaritana, Evangelho da Quaresma.', true, 'spotify'),
  ('salve-o-cristo-obediente', 'Salve, ó Cristo obediente', 'Cantos do Hinário Litúrgico da CNBB', array['quaresma']::text[], array['retiro','pregação']::text[], 'https://open.spotify.com/track/1TXLEeMMmpGSjfIfcToJXY', 'Saúda o Cristo obediente até a cruz, tema do caminho quaresmal.', true, 'spotify'),
  ('maranata-vem-senhor-jesus', 'Maranata Vem Senhor Jesus (Comunhão)', 'Sacrum Music', array['advento']::text[], array['retiro','adoração','pregação']::text[], 'https://open.spotify.com/track/6s9QWQKnIvxG2WA8ZWkJhY', 'O clamor ''Maranata'' expressa a espera pela vinda do Senhor, essência do Advento.', true, 'spotify'),
  ('o-filho-do-homem-vira-sobre-as-nuvens', 'O Filho do Homem Virá Sobre as Nuvens (Entrada)', 'Sacrum Music', array['advento']::text[], array['retiro','pregação']::text[], 'https://open.spotify.com/track/6VlVgi4IpB6z2asOekdkga', 'Anuncia a vinda gloriosa do Filho do Homem, tema escatológico do Advento.', true, 'spotify'),
  ('que-venha-o-teu-reino', 'Que Venha o Teu Reino (Ofertório)', 'Sacrum Music', array['advento']::text[], array['retiro','pregação','grupo de oração']::text[], 'https://open.spotify.com/track/6Zgipb9DncMn3i7PMXUrIi', 'O pedido pela vinda do Reino traduz a espera vigilante do Advento.', true, 'spotify'),
  ('senhor-que-vindes-visitar-vosso-povo', 'Senhor que vindes visitar vosso povo na paz (Ato Penitencial)', 'Sacrum Music', array['advento','perdao']::text[], array['retiro','pregação']::text[], 'https://open.spotify.com/track/0sldDr7aIL2r96RdeLtgZo', 'Une a espera do Senhor que vem com o pedido de perdão próprio do Advento.', true, 'spotify')
insert into public.preachers (id, name, description, official_url, themes) values
  ('padre-paulo-ricardo', 'Padre Paulo Ricardo', 'Sacerdote da Arquidiocese de Cuiabá, dedicado à formação doutrinária e espiritual.', 'https://padrepauloricardo.org', array['palavra-de-deus','santidade','oracao','eucaristia']::text[]),
  ('padre-fabio-de-melo', 'Padre Fábio de Melo', 'Sacerdote, cantor e escritor; pregações sobre afetividade, esperança e humanidade.', null, array['fe-e-esperanca','amor-de-deus','sofrimento-e-cruz']::text[]),
  ('padre-marcelo-rossi', 'Padre Marcelo Rossi', 'Sacerdote da Diocese de Santo Amaro (SP), ligado ao Santuário Mãe de Deus.', null, array['cura-e-libertacao','fe-e-esperanca','louvor']::text[]),
  ('padre-reginaldo-manzotti', 'Padre Reginaldo Manzotti', 'Sacerdote da Arquidiocese de Curitiba, fundador da Associação Evangelizar é Preciso.', null, array['missao','fe-e-esperanca','maria']::text[]),
  ('frei-gilson', 'Frei Gilson', 'Religioso carmelita, conhecido pela oração do terço e pela música católica.', null, array['oracao','maria','conversao']::text[]),
  ('monsenhor-jonas-abib', 'Monsenhor Jonas Abib', 'Fundador da Comunidade Canção Nova (falecido em 2022); vasto acervo de pregações.', 'https://www.cancaonova.com', array['espirito-santo','conversao','santidade']::text[]),
  ('padre-leo-scj', 'Padre Léo, SCJ', 'Sacerdote dehoniano, fundador da Comunidade Bethânia (falecido em 2007).', null, array['cura-e-libertacao','amor-de-deus','familia']::text[]),
  ('padre-antonio-maria', 'Padre Antônio Maria', 'Sacerdote e cantor; pregações de devoção mariana e vida cristã.', null, array['maria','louvor']::text[]),
  ('marcio-mendes', 'Márcio Mendes', 'Missionário da Comunidade Canção Nova e pregador.', null, array['cura-e-libertacao','perdao','espirito-santo']::text[]),
  ('dunga', 'Dunga', 'Missionário da Comunidade Canção Nova, pregador e cantor, ligado ao projeto PHN para jovens.', null, array['santidade','missao']::text[]),
  ('padre-chrystian-shankar', 'Padre Chrystian Shankar', 'Sacerdote mineiro, pregações sobre vida espiritual e relacionamentos.', null, array['familia','fe-e-esperanca']::text[]),
  ('padre-roger-araujo', 'Padre Roger Araújo', 'Sacerdote da Comunidade Canção Nova.', null, array['oracao','palavra-de-deus']::text[]),
  ('moyses-azevedo', 'Moysés Azevedo', 'Fundador da Comunidade Católica Shalom.', null, array['missao','espirito-santo','santidade']::text[]),
  ('ironi-spuldaro', 'Ironi Spuldaro', 'Missionário leigo e pregador católico.', null, array['cura-e-libertacao','conversao']::text[])
